begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into public.calendar_event_colors(value) values ('BLUE'),('PURPLE'),('GREEN') on conflict do nothing;
insert into auth.users(id) values('00000000-0000-4000-8000-000000008801'),('00000000-0000-4000-8000-000000008802');
insert into public.users(id) values('00000000-0000-4000-8000-000000008801'),('00000000-0000-4000-8000-000000008802') on conflict do nothing;
insert into public.workspaces(id,name,personal,creator_id) values('00000000-0000-0000-0000-000000000000','Desktop fixture',false,'00000000-0000-4000-8000-000000008801') on conflict(id) do update set creator_id=excluded.creator_id;
insert into public.workspace_members(ws_id,user_id,type) values('00000000-0000-0000-0000-000000000000','00000000-0000-4000-8000-000000008801','MEMBER') on conflict do nothing;
select is((select count(*)::integer from private.desktop_deployment_environments where enabled),0,'every platform starts disabled');
select ok(not has_table_privilege('authenticated','private.desktop_deployment_resources','SELECT'),'authenticated clients cannot read ciphertext');
select ok(not has_table_privilege('anon','private.desktop_deployment_ci_tokens','SELECT'),'anonymous clients cannot read token hashes');
select ok(not has_function_privilege('authenticated','private.desktop_deployment_create_version(uuid,text,text)','EXECUTE'),'private admin RPC is service-only');
select throws_ok($$select private.desktop_deployment_assert_admin(null)$$,'42501','desktop_vault_forbidden','missing actor denied');
select throws_ok($$select private.desktop_deployment_assert_admin('00000000-0000-4000-8000-000000008802')$$,'42501','desktop_vault_forbidden','nonmember denied even if workspace defaults permit');
insert into public.workspace_members(ws_id,user_id,type) values('00000000-0000-0000-0000-000000000000','00000000-0000-4000-8000-000000008802','MEMBER');
update public.workspace_default_permissions set enabled=false where ws_id='00000000-0000-0000-0000-000000000000';
select throws_ok($$select private.desktop_deployment_assert_admin('00000000-0000-4000-8000-000000008802')$$,'42501','desktop_vault_forbidden','membership alone is insufficient');
create temp table fixture_version as select value.* from private.desktop_deployment_create_version('00000000-0000-4000-8000-000000008801','windows','fixture-encrypted-key') value;
select is((select revision from fixture_version),1::bigint,'draft starts revision one');
select throws_ok($$select private.desktop_deployment_create_version('00000000-0000-4000-8000-000000008801','windows','fixture')$$,'23505',null,'only one draft per platform');
select throws_ok($$select private.desktop_deployment_validate_version('00000000-0000-4000-8000-000000008801',(select id from fixture_version),1,'{}')$$,'P0001','desktop_profile_incomplete','incomplete version cannot be ready');
select throws_ok($$select private.desktop_deployment_write_resource('00000000-0000-4000-8000-000000008801',(select id from fixture_version),1,'APPLE_TEAM_ID','fixture',repeat('a',64),10)$$,'23514',null,'cross-platform scalar denied');
select throws_ok($$select private.desktop_deployment_write_resource('00000000-0000-4000-8000-000000008801',(select id from fixture_version),1,'GOOGLE_PLAY_SERVICE_ACCOUNT','fixture',repeat('a',64),10)$$,'23514',null,'mobile credentials denied');
select is(private.desktop_deployment_write_resource('00000000-0000-4000-8000-000000008801',(select id from fixture_version),1,'windows_authenticode_certificate_pfx','fixture-encrypted-pfx',repeat('a',64),32),2::bigint,'first resource increments exactly once');
select throws_ok($$select private.desktop_deployment_write_resource('00000000-0000-4000-8000-000000008801',(select id from fixture_version),1,'WINDOWS_SIGNING_CERTIFICATE_PASSWORD','fixture',repeat('b',64),4)$$,'40001','desktop_version_conflict','stale write rejected');
select is(private.desktop_deployment_write_resource('00000000-0000-4000-8000-000000008801',(select id from fixture_version),2,'WINDOWS_SIGNING_CERTIFICATE_PASSWORD','fixture-encrypted-password',repeat('b',64),4),3::bigint,'second resource increments exactly once');
select lives_ok($$select private.desktop_deployment_validate_version('00000000-0000-4000-8000-000000008801',(select id from fixture_version),3,'{}')$$,'service validation binds complete profile revision');
select is(private.desktop_deployment_write_resource('00000000-0000-4000-8000-000000008801',(select id from fixture_version),3,'WINDOWS_SIGNING_CERTIFICATE_PASSWORD','fixture-replacement',repeat('c',64),4),4::bigint,'upsert increments once rather than insert plus update');
select ok((select validated_revision is null from private.desktop_deployment_versions where id=(select id from fixture_version)),'editing invalidates readiness');
select throws_ok($$select private.desktop_deployment_activate_version('00000000-0000-4000-8000-000000008801',(select id from fixture_version),4)$$,'40001','desktop_version_not_ready','edited version cannot activate without validation');
select throws_ok($$update private.desktop_deployment_versions set data_key_ciphertext='changed' where id=(select id from fixture_version)$$,'P0001','desktop_version_identity_immutable','encrypted key identity is immutable');
select lives_ok($$select private.desktop_deployment_validate_version('00000000-0000-4000-8000-000000008801',(select id from fixture_version),4,'{}')$$,'latest complete revision validates');
select lives_ok($$select private.desktop_deployment_activate_version('00000000-0000-4000-8000-000000008801',(select id from fixture_version),4)$$,'ready version activates');
select is((select count(*)::integer from private.desktop_deployment_environments where enabled),0,'activation never enables delivery');
select throws_ok($$select private.desktop_deployment_write_resource('00000000-0000-4000-8000-000000008801',(select id from fixture_version),4,'WINDOWS_SIGNING_CERTIFICATE_PASSWORD','fixture',repeat('d',64),4)$$,'40001','desktop_version_conflict','active credentials immutable through RPC');
select throws_ok($$delete from private.desktop_deployment_resources where version_id=(select id from fixture_version)$$,'P0001','desktop_version_immutable','direct service delete cannot mutate active credentials');
create temp table fixture_token as select value.* from private.desktop_deployment_create_token('00000000-0000-4000-8000-000000008801',(select id from fixture_version),'Fixture','ttr_desktop_ci_fixture',repeat('f',64),now()+interval '1 day') value;
select throws_ok($$select private.desktop_deployment_reserve_bundle((select id from fixture_token),'windows','100','1',repeat('a',40))$$,'42501','desktop_bundle_denied','disabled admission denies bundle');
update private.desktop_deployment_environments set enabled=true where platform='windows';
select throws_ok($$select private.desktop_deployment_reserve_bundle((select id from fixture_token),'macos','100','1',repeat('a',40))$$,'42501','desktop_bundle_denied','token platform is exact');
create temp table fixture_lease as select value.* from private.desktop_deployment_reserve_bundle((select id from fixture_token),'windows','100','1',repeat('a',40)) value;
select is((select status from fixture_lease),'reserved','reservation is durable before decryption');
select throws_ok($$select private.desktop_deployment_reserve_bundle((select id from fixture_token),'windows','100','1',repeat('a',40))$$,'23505',null,'same run attempt cannot reserve twice');
select lives_ok($$select private.desktop_deployment_complete_bundle((select id from fixture_lease))$$,'live authorized reservation completes');
select throws_ok($$select private.desktop_deployment_complete_bundle((select id from fixture_lease))$$,'40001','desktop_lease_consumed','delivered lease cannot replay');
create temp table revoked_lease as select value.* from private.desktop_deployment_reserve_bundle((select id from fixture_token),'windows','100','2',repeat('a',40)) value;
select lives_ok($$select private.desktop_deployment_revoke_token('00000000-0000-4000-8000-000000008801',(select id from fixture_token))$$,'admin revokes CI token');
select throws_ok($$select private.desktop_deployment_complete_bundle((select id from revoked_lease))$$,'42501','desktop_bundle_denied','revocation during decrypt prevents delivery');
select lives_ok($$select private.desktop_deployment_complete_bundle((select id from revoked_lease),'token_revoked')$$,'fixed failure can consume revoked reservation');
select throws_ok($$select private.desktop_deployment_complete_bundle((select id from revoked_lease),'retry')$$,'40001','desktop_lease_consumed','failed lease cannot replay');
select throws_ok($$select private.desktop_deployment_reserve_bundle((select id from fixture_token),'windows','100','3',repeat('a',40))$$,'42501','desktop_bundle_denied','revoked token cannot reserve');
select is((select count(*)::integer from private.desktop_deployment_audit_events where event_type='bundle.delivered'),1,'only successful delivery is audited as delivered');
select is((select count(*)::integer from private.desktop_deployment_audit_events where event_type='bundle.failed'),1,'decryption/admission failure recorded without sensitive payload');
create temp table next_version as select value.* from private.desktop_deployment_create_version('00000000-0000-4000-8000-000000008801','windows','fixture-next-key') value;
select is((select version from next_version),2,'rotation creates next monotonic draft');
select is(private.desktop_deployment_write_resource('00000000-0000-4000-8000-000000008801',(select id from next_version),1,'WINDOWS_SIGNING_CERTIFICATE_PASSWORD','fixture',repeat('c',64),4),2::bigint,'new draft accepts profile write');
select is(private.desktop_deployment_remove_resource('00000000-0000-4000-8000-000000008801',(select id from next_version),2,'WINDOWS_SIGNING_CERTIFICATE_PASSWORD'),3::bigint,'removal invalidates revision once');
select throws_ok($$select private.desktop_deployment_remove_resource('00000000-0000-4000-8000-000000008801',(select id from next_version),3,'WINDOWS_SIGNING_CERTIFICATE_PASSWORD')$$,'P0002','desktop_resource_missing','missing resource removal is explicit');
select * from finish();
rollback;
